import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"Why Agents Need to Pay: APIs, Data, Compute, and Other Agents","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/why-agents-pay.md","filePath":"learn/02-agent-payments/why-agents-pay.md","lastUpdated":1792595354000}'),s={name:"learn/02-agent-payments/why-agents-pay.md"};function o(d,e,i,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="why-agents-need-to-pay-apis-data-compute-and-other-agents" tabindex="-1">Why Agents Need to Pay: APIs, Data, Compute, and Other Agents <a class="header-anchor" href="#why-agents-need-to-pay-apis-data-compute-and-other-agents" aria-label="Permalink to &quot;Why Agents Need to Pay: APIs, Data, Compute, and Other Agents&quot;">​</a></h1><p>Traditional chat applications mainly incur model inference costs. An agent that acts in the world also consumes external resources: search and specialist APIs, commercial datasets, cloud compute, paid tools, and services provided by other agents. As the agent becomes more capable, payment becomes a runtime requirement rather than an occasional add-on.</p><h2 id="what-agents-may-buy" tabindex="-1">What agents may buy <a class="header-anchor" href="#what-agents-may-buy" aria-label="Permalink to &quot;What agents may buy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Examples</th><th>Common pricing</th></tr></thead><tbody><tr><td>APIs</td><td>Search, weather, maps, OCR</td><td>Per call or request volume</td></tr><tr><td>Commercial data</td><td>Market data, research, company records</td><td>Per record, query, or item</td></tr><tr><td>Elastic compute</td><td>Code sandboxes, model inference, browsers</td><td>Per second, token, or instance</td></tr><tr><td>Tools and agents</td><td>Specialist MCP tools, expert sub-agents</td><td>Per call or result</td></tr><tr><td>Real-world services</td><td>Travel, cloud services, online purchases</td><td>Per item or transaction</td></tr></tbody></table><p>Many agent-native purchases are small, frequent, and directed to providers discovered dynamically. A workflow may make dozens of calls, each to a different service. Traditional card fees, subscriptions, and manually managed API keys may be awkward for this pattern. The trade-offs are discussed in <a href="./payment-options">Payment Options Compared</a>.</p><h2 id="why-not-ask-a-person-every-time" tabindex="-1">Why not ask a person every time? <a class="header-anchor" href="#why-not-ask-a-person-every-time" aria-label="Permalink to &quot;Why not ask a person every time?&quot;">​</a></h2><p>Per-call approval can create alert fatigue. It also prevents unattended jobs from completing when no person is available. The answer is not unrestricted spending: set policy in advance, then enforce per-transaction limits, cumulative budgets, approved recipients, rate limits, and escalation rules independently of the model.</p><h2 id="a-separate-control-layer" tabindex="-1">A separate control layer <a class="header-anchor" href="#a-separate-control-layer" aria-label="Permalink to &quot;A separate control layer&quot;">​</a></h2><p>The developer should not have to pre-register for every long-tail service or expose reusable credentials to every agent. A payment system for agents needs to bind identity and authorization to each request, enforce limits, make retries safe, and preserve an audit trail. The model may propose that a resource is useful; trusted code decides whether the agent may pay for it.</p>',9)])])}const y=a(s,[["render",o]]);export{m as __pageData,y as default};
